#include <bits/stdc++.h>
using namespace std;

int main() {
	// your code goes here
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	
	int t;
	cin >> t;
	while(t--){
	    int n ;
	    cin >> n;
	    
	    int N = 3 * n;
	    
	    vector<long long> a(N);
	    for(auto &x : a){
	        cin >> x;
	    }
	    sort(a.begin(),a.end());
	    
	    vector<long long> pref(N+1,0);
	    
	    for(int i = 0 ;i <  N ; i++){
	        pref[i+1] = pref[i] + a[i];
	    }
	    auto sumb = [&](int cnt)-> long long {
	        return pref[cnt];
	    };
	    auto sumt = [&](int cnt) -> long long{
	        return pref[N] - pref[N - cnt];
	    };
	    
	    auto bon = [&](int k , int l) -> long long{
	        return sumt(k + 2  * l) + 2LL * sumt(k) - 3LL * sumb(2 * k + l);
	    };
	    
	    int l = n;
	    long long best = 0;
	    for(int k = 0 ; k <= n ; k++){
	        l = min( l , n - k);
	        
	        while( l > 0){
	            int q1 = k + 2 * (l - 1);
	            int q2  = q1 + 1;
	            
	            long long add1 = a[N - q1 - 1];
	            long long add2 = a[N - q2 - 1];
	            
	            long long rem = a[2 * k + l - 1];
	            long long delta = add1 + add2 - 3LL * rem;
	            
	            if(delta < 0){
	                l--;
	            }else{
	                break;
	            }
	        }
	        
	        best = max(best , bon(k,l));
	    }
	    long long bas = 3LL * pref[N];
	    
	    cout << bas + best << endl;
	}

}
